public class ProductsControllerTests
{
    [Fact]
    public async Task Get_WhenProductExists_ReturnsOkResult()
    {
        // Arrange
        var mockRepo = new Mock<IProductRepository>();
        mockRepo.Setup(repo => repo.GetByIdAsync(1))
            .ReturnsAsync(new Product { Id = 1, Name = "Laptop", Price = 999m });

        var controller = new ProductsController(mockRepo.Object);

        // Act
        var result = await controller.Get(1);

        // Assert
        var okResult = Assert.IsType<OkObjectResult>(result.Result);
        var product = Assert.IsType<Product>(okResult.Value);
        Assert.Equal("Laptop", product.Name);
    }

    [Fact]
    public async Task Get_WhenProductNotFound_ReturnsNotFound()
    {
        // Arrange
        var mockRepo = new Mock<IProductRepository>();
        mockRepo.Setup(repo => repo.GetByIdAsync(It.IsAny<int>()))
            .ReturnsAsync((Product?)null);

        var controller = new ProductsController(mockRepo.Object);

        // Act
        var result = await controller.Get(999);

        // Assert
        Assert.IsType<NotFoundResult>(result.Result);
    }
}

public class OrdersControllerTests
{
    private readonly Mock<IOrderRepository> _mockRepo;
    private readonly OrdersController _controller;

    public OrdersControllerTests()
    {
        _mockRepo = new Mock<IOrderRepository>();
        _controller = new OrdersController(_mockRepo.Object);
    }

    [Fact]
    public async Task Create_ValidOrder_ReturnsCreatedAtAction()
    {
        // Arrange
        var request = new CreateOrderRequest { ProductId = 1, Quantity = 2 };
        var createdOrder = new Order { Id = 1, ProductId = 1, Quantity = 2 };
        _mockRepo.Setup(r => r.CreateAsync(It.IsAny<Order>())).ReturnsAsync(createdOrder);

        // Act
        var result = await _controller.Create(request);

        // Assert
        var actionResult = Assert.IsType<CreatedAtActionResult>(result.Result);
        var returnedOrder = Assert.IsType<Order>(actionResult.Value);
        Assert.Equal(1, returnedOrder.Id);
        Assert.Equal("Orders", actionResult.ActionName);
    }
}
